export const MUSEUM_KNOWLEDGE_INDEX=Object.freeze({"version":"museum-buran-20261030-v1","edition":"museum-buran-20261030-v1","sourceRevision":"1d70e1955ed31bf8","sites":{"pad-110":{"id":"pad-110","title":"Площадка 110 · старт «Энергии — Бурана»","subtitle":"Н1 → «Энергия — Буран»","summary":"Два старта лунной программы Н1 стали основой комплекса «Энергии — Бурана». Для полёта 15 ноября 1988 года использовали левую пусковую установку; соседний правый старт в съёмке 1988 года ещё строится."},"pad-250":{"id":"pad-250","title":"Площадка 250 · УКСС","subtitle":"Универсальный комплекс стенд-старт","summary":"Здесь наземные испытания тяжёлой ракеты сочетались с возможностью пуска. 15 мая 1987 года с УКСС впервые стартовала «Энергия» с аппаратом «Полюс»."},"pad-112":{"id":"pad-112","title":"Площадка 112 · МИК и «Кузнечики»","subtitle":"Сборка · стыковка · вывоз","summary":"В корпусе, созданном для Н1 и переоборудованном под «Энергию», собирали ракету и соединяли её с «Бураном». На старт система отправлялась горизонтально на транспортно-установочном агрегате."},"pad-112a":{"id":"pad-112a","title":"Площадка 112А · МЗК и СДИ","subtitle":"Заключительная подготовка и испытания","summary":"Монтажно-заправочный комплекс завершал подготовку уже состыкованной системы. Соседний стенд динамических испытаний предназначался для исследования её колебаний."},"pad-251":{"id":"pad-251","title":"Площадка 251 · Юбилейный","subtitle":"Посадочный комплекс «Бурана»","summary":"Посадочный комплекс орбитального корабля: бетонная ВПП 4500 × 84 м, рулёжные дорожки, ОКДП и средства «Вымпела». 15 ноября 1988 года «Буран» приземлился здесь автоматически. Кнопка «ПОСАДКА БУРАНА» запускает реконструкцию возвращения с МиГ-25 и исторической хронологией."},"pad-1":{"id":"pad-1","title":"Площадка 1 · Гагаринский старт","subtitle":"Два начала космической эпохи","summary":"С этого старта отправились первый искусственный спутник Земли и первый человек, совершивший орбитальный полёт. Историю площадки продолжают разные поколения семейства Р-7."},"pad-31":{"id":"pad-31","title":"Площадка 31 · старт «Союза»","subtitle":"Ракетное семейство Р-7","summary":"Площадка использовалась для пилотируемых запусков «Союза». Архив ESA документирует здесь вывоз и пуск «Союза ТМА-15М» в ноябре 2014 года."},"pad-81":{"id":"pad-81","title":"Площадка 81 · «Протон»","subtitle":"Тяжёлый носитель и его наземный комплекс","summary":"В руководстве ILS для коммерческих пусков «Протона» указана площадка 81, пусковая установка 24. Архивный документ описывает инфраструктуру периода своей публикации."},"pad-200":{"id":"pad-200","title":"Площадка 200 · «Протон»","subtitle":"Тяжёлый носитель и его наземный комплекс","summary":"В руководстве ILS для коммерческих пусков «Протона» указана площадка 200, пусковая установка 39. Архивный документ описывает инфраструктуру периода своей публикации."},"pad-45":{"id":"pad-45","title":"Площадка 45 · «Зенит» и «Союз-5»","subtitle":"«Зенит» → «Байтерек»","summary":"Площадка запусков «Зенита» переоборудована под «Союз-5» в рамках проекта «Байтерек». Первый испытательный пуск «Союза-5» отсюда состоялся 30 апреля 2026 года. Выберите «Зенит» или «Союз-5», чтобы открыть модель и её характеристики."},"pad-5":{"id":"pad-5","title":"Площадка № 5 · Радиопередающий центр","subtitle":"ПДРЦ · связь и единое время полигона","summary":"Передающий радиоцентр связывал ЦУС «Агат» с удалёнными радиокорреспондентами. Приёмная часть радиоцентра находилась на площадке № 4.","evidenceType":"documented"}},"rockets":{"soyuz":{"id":"soyuz","title":"«Союз» · пилотируемая компоновка","subtitle":"Ракета-экспонат на площадках 1 и 31","summary":"Четыре боковых блока вокруг центрального и головная часть с системой аварийного спасения создают узнаваемый силуэт пилотируемого «Союза». Экспонат показывает эту компоновку семейства Р-7."},"energia":{"id":"energia","title":"«Энергия»","subtitle":"Тяжёлая ракета-носитель · 11К25","summary":"Ракета создавалась для разных крупных нагрузок: крылатого орбитального корабля или отдельного грузового аппарата сбоку центрального блока. В 1987 и 1988 годах состоялись два её пуска."},"energia-polyus":{"id":"energia-polyus","title":"«Энергия — Полюс»","subtitle":"Первый пуск · 15 мая 1987 года","summary":"Первую «Энергию» вывели на испытательный полёт с крупным боковым аппаратом 17Ф19ДМ «Скиф-ДМ», известным как «Полюс». Ракета выполнила свою часть программы; аппарат не достиг орбиты после отделения."},"energia-buran":{"id":"energia-buran","title":"«Энергия — Буран»","subtitle":"Ракетно-космическая система · 11Ф36","summary":"Связка тяжёлой ракеты и крылатого орбитального корабля стартовала 15 ноября 1988 года. Корабль выполнил два витка и автоматически приземлился на Байконуре."},"energia-m":{"id":"energia-m","title":"«Энергия-М»","subtitle":"Проект · полноразмерный макет проходил примерки","summary":"Уменьшенный вариант семейства должен был использовать производственный и наземный задел «Энергии». Он дошёл до полноразмерного технологического макета и примерочных испытаний, но не до космического полёта."},"buran":{"id":"buran","title":"«Буран» · орбитальный корабль","subtitle":"Крылатый корабль · 11Ф35","summary":"Корабль возвращался из космоса планированием и садился на аэродром. В техническом проекте большой грузовой отсек предназначался для доставки и возвращения полезных грузов."},"tua":{"id":"tua","title":"«Кузнечики» · ТУА","subtitle":"Транспортно-установочные агрегаты","summary":"Эти тяжёлые машины перевозили ракетно-космическую систему горизонтально, а на стартовой позиции участвовали в её установке. ТУА программы «Энергия» происходили от транспортных средств Н1."},"proton":{"id":"proton","title":"«Протон-М / Бриз-М»","subtitle":"Справочная компоновка для единого масштаба","summary":"Три ступени ракеты сочетаются с многократно включаемым разгонным блоком. Точная общая длина зависит от полезного груза и обтекателя."},"zenit":{"id":"zenit","title":"«Зенит-2»","subtitle":"Базовая двухступенчатая компоновка","summary":"Двухступенчатая ракета на кислороде и керосине разрабатывалась одновременно с унифицированными боковыми блоками «Энергии»."}},"stories":{"abort-51":{"id":"abort-51","title":"51 секунда до старта","subtitle":"29 октября 1988 · площадка 110","summary":"Первый назначенный пуск «Бурана» остановился почти у самой точки старта.","siteId":"pad-110","evidenceType":"documented"},"coins-under-tua":{"id":"coins-under-tua","title":"Монетки под 3 500 тоннами","subtitle":"10 октября 1988 · вывоз на старт","summary":"Во время вывоза гигантской машины нашлось место маленькому сувениру.","siteId":"pad-112","evidenceType":"recollection"},"runway-profilometer":{"id":"runway-profilometer","title":"Самолёт измерял бетон","subtitle":"30 октября 1986 · Юбилейный","summary":"Ровность посадочной полосы проверяли летающей лабораторией.","siteId":"pad-251","evidenceType":"recollection"},"dmb-inscription":{"id":"dmb-inscription","title":"Надпись ДМБ: две версии","subtitle":"1988 · история из воспоминаний","summary":"На buran.ru сохранены расходящиеся рассказы о повреждённой теплоизоляции и надписи «ДМБ».","siteId":"pad-110","evidenceType":"disputed"},"mriya-after-flight":{"id":"mriya-after-flight","title":"«Мрия» появилась после полёта","subtitle":"1988–1989 · воздушная перевозка","summary":"Знаменитая пара Ан-225 и «Буран» не должна заслонять работу более раннего самолёта.","siteId":"pad-251","evidenceType":"documented"},"polyus-turn":{"id":"polyus-turn","title":"Поворот, после которого орбиты не было","subtitle":"15 мая 1987 · первый пуск «Энергии»","summary":"Успешная работа носителя и выход полезной нагрузки на орбиту — разные этапы полёта.","siteId":"pad-250","evidenceType":"documented"},"energia-m-winter":{"id":"energia-m-winter","title":"Ракета, вышедшая на старт зимой","subtitle":"25–26 декабря 1991 · УКСС","summary":"«Энергия-М» не летала, но её полноразмерный макет действительно побывал на старте.","siteId":"pad-250","evidenceType":"documented"},"jet-buran":{"id":"jet-buran","title":"«Буран», который взлетал как самолёт","subtitle":"БТС-002 ОК-ГЛИ · атмосферные испытания","summary":"У атмосферного аналога были четыре турбореактивных двигателя.","siteId":"pad-251","evidenceType":"documented"},"evacuation-slide":{"id":"evacuation-slide","title":"Запасной путь через «склиз»","subtitle":"Площадка 110 · безопасность экипажа","summary":"Две наклонные трубы у башни предназначались для людей.","siteId":"pad-110","evidenceType":"recollection"},"landing-turn":{"id":"landing-turn","title":"Почему корабль повернул не туда, куда ждали","subtitle":"15 ноября 1988 · автоматическая посадка","summary":"Неожиданный для наблюдателей манёвр стал основой рассказов о «самостоятельном решении» корабля.","siteId":"pad-251","evidenceType":"documented"},"baikal-secret-flight":{"id":"baikal-secret-flight","title":"«Тайный второй полёт» оказался розыгрышем","subtitle":"1 апреля 2000 · легенда о «Байкале»","summary":"Текст о секретном полёте «Байкала» 2 февраля 1992 года — первоапрельская история.","siteId":"pad-110","evidenceType":"hoax"},"which-buran":{"id":"which-buran","title":"Какой именно «Буран» перед нами?","subtitle":"Лётные корабли, аналоги и макеты","summary":"Похожий силуэт скрывает разные испытательные биографии.","siteId":"pad-112","evidenceType":"documented"}},"evidenceTypes":{"documented":{"label":"Документированный факт"},"recollection":{"label":"Воспоминание участника"},"disputed":{"label":"Спорная история"},"hoax":{"label":"Первоапрельский розыгрыш"}},"sourceCount":46,"sourceConflictCount":6});
